-- 420: Original BrillaPrep WASSCE Integrated Science beta questions, part 8 of 8 (sprint 1 batch 001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_420_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_420_guard;
INSERT INTO _migration_420_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_reproduction_b001_003' AND NOT (q.topic_id IS 'topic_wassce_intsci_reproduction' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'In humans, fertilisation of the egg normally takes place in the:' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Ovary","B. Uterus","C. Oviduct (fallopian tube)","D. Vagina"]' AND q.correct_answer IS 'C' AND q.explanation IS 'After ovulation the egg travels along the oviduct, where it may meet sperm and be fertilised; the embryo then implants in the uterus. The ovary releases the egg but is not the site of fertilisation.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_reproduction_b001_003' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_420_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_reproduction_b001_004' AND NOT (q.topic_id IS 'topic_wassce_intsci_reproduction' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'In genetics, an allele is:' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. An alternative form of a gene","B. A chromosome found only in males","C. The physical appearance of an organism","D. A cell that carries gametes"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Alleles are alternative versions of the same gene, for example T (tall) and t (short) in pea plants. The physical appearance produced by the alleles is the phenotype, which is a different concept.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_reproduction_b001_004' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_420_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_reproduction_b001_005' AND NOT (q.topic_id IS 'topic_wassce_intsci_reproduction' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Two heterozygous tall pea plants (Tt × Tt) are crossed, where the allele T for tallness is dominant over t for shortness. The expected genotypic ratio of the offspring is:' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 3 tall : 1 short","B. 1 TT : 2 Tt : 1 tt","C. 1 Tt : 1 tt","D. All Tt"]' AND q.correct_answer IS 'B' AND q.explanation IS 'A Punnett square for Tt × Tt gives TT, Tt, Tt and tt, a genotypic ratio of 1 : 2 : 1. The 3 : 1 ratio is the phenotypic ratio (three tall to one short), which describes appearance, not genotype.' AND q.difficulty IS 'hard' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_reproduction_b001_005' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_420_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_reproduction_b001_006' AND NOT (q.topic_id IS 'topic_wassce_intsci_reproduction' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'In humans, the sex of a child is determined by:' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Whether the egg carries an X or a Y chromosome","B. The number of chromosomes in the mother’s blood","C. Whether the fertilising sperm carries an X or a Y chromosome","D. The age of the mother at conception"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Every egg carries an X chromosome, while each sperm carries either X or Y. An X-carrying sperm gives an XX (female) zygote and a Y-carrying sperm an XY (male) zygote, so the sperm determines sex.' AND q.difficulty IS 'hard' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_reproduction_b001_006' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_420_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_enr_b001_009' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_enr' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A 6 Ω resistor is connected across a 12 V battery. Calculate (a) the current flowing through the resistor and (b) the power dissipated by the resistor.' AND q.question_type IS 'calculation' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '(a) 2 A (b) 24 W' AND q.explanation IS '(a) By Ohm’s law, current I = V ÷ R = 12 V ÷ 6 Ω = 2 A. (b) Power P = V × I = 12 V × 2 A = 24 W (equivalently P = I²R = (2 A)² × 6 Ω = 24 W). Both parts must carry the correct units to earn full marks.' AND q.difficulty IS 'medium' AND q.points IS '4' AND q.marks IS '2' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_enr_b001_009' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_420_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_enr_b001_010' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_enr' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'An electric kettle is rated at 2 000 W. Calculate the electrical energy it consumes when it is used for 5 minutes, giving your answer in joules.' AND q.question_type IS 'calculation' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '600 000 J (600 kJ)' AND q.explanation IS 'Energy E = power × time, with time in seconds: t = 5 × 60 = 300 s. So E = 2 000 W × 300 s = 600 000 J = 600 kJ. A common error is to multiply 2 000 by 5 (giving 10 000 J), forgetting to convert minutes to seconds.' AND q.difficulty IS 'medium' AND q.points IS '4' AND q.marks IS '2' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_enr_b001_010' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wisc_reproduction_b001_003', 'topic_wassce_intsci_reproduction', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'In humans, fertilisation of the egg normally takes place in the:', 'multiple_choice', NULL, '["A. Ovary","B. Uterus","C. Oviduct (fallopian tube)","D. Vagina"]', 'C', 'After ovulation the egg travels along the oviduct, where it may meet sperm and be fertilised; the embryo then implants in the uterus. The ovary releases the egg but is not the site of fertilisation.', 'medium', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, NULL);
